#include "construction/PrefabRegistry.hpp"
#include <algorithm>
#include <cmath>
namespace elysium::construction {bool PrefabRegistry::add(PrefabDef d){if(!d.id||defs_.contains(d.id))return false;d.mask.permeability=std::isfinite(d.mask.permeability)?std::clamp(d.mask.permeability,0.0,1.0):0.0;std::sort(d.costs.begin(),d.costs.end(),[](auto&a,auto&b){return std::tie(a.substitutionGroup,a.content,a.amount)<std::tie(b.substitutionGroup,b.content,b.amount);});defs_[d.id]=std::move(d);return true;}const PrefabDef*PrefabRegistry::find(ContentId id)const{auto i=defs_.find(id);return i==defs_.end()?nullptr:&i->second;}std::vector<std::string>PrefabRegistry::validate()const{std::vector<std::string>o;for(auto&[id,d]:defs_){if(d.sizeX<=0||d.sizeY<=0||d.sizeZ<=0)o.push_back("invalid_footprint");if(d.allowedRotationMask==0)o.push_back("no_legal_rotation");if(d.family==ShapeFamily::Railing&&d.mask.seal)o.push_back("railing_false_seal");if(d.family==ShapeFamily::Decor&&d.mask.support)o.push_back("decor_false_support");if(d.mask.seal&&d.mask.permeability>0)o.push_back("seal_permeability_conflict");for(auto&c:d.costs)if(!c.content||!c.amount)o.push_back("invalid_cost_line");}return o;}SnapResult PrefabRegistry::preview(SnapRequest r)const{auto*d=find(r.prefabId);if(!d)return{false,"unknown_prefab",r,{},{}};r.quarterTurn%=4;if((d->allowedRotationMask&(1u<<r.quarterTurn))==0)return{false,"rotation_not_allowed",r,d->mask,d->costs};if(r.mirror&&!d->mirrorAllowed)return{false,"mirror_not_allowed",r,d->mask,d->costs};if(r.anchor!=d->anchor)return{false,"anchor_mismatch",r,d->mask,d->costs};return{true,"",r,d->mask,d->costs};}}
